module pdm_cic_precedence (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        i_pdm,
    output wire [31:0] o_pcm
);
    localparam [31:0] DEC = 32'd64;

    reg [31:0] integ1;
    reg [31:0] integ2;
    reg [31:0] dly1;
    reg [31:0] dly2;
    reg [31:0] pcm;
    reg [31:0] phase;
    reg        seen_one;
    reg        armed;

    initial integ1   = 32'd0;
    initial integ2   = 32'd0;
    initial dly1     = 32'd0;
    initial dly2     = 32'd0;
    initial pcm      = 32'd0;
    initial phase    = 32'd0;
    initial seen_one = 1'b0;
    initial armed    = 1'b0;

    wire [31:0] integ1_n = integ1 + {31'd0, i_pdm};
    wire [31:0] integ2_n = integ2 + integ1;
    wire [31:0] comb1    = integ2 - dly1;
    wire [31:0] comb2    = comb1 - dly2;
    wire        tick     = (phase == DEC - 32'd1);

    always @(posedge clk) begin
        if (i_ce) begin
            integ1 <= integ1_n;
            integ2 <= integ2_n;
            if (i_pdm)
                seen_one <= 1'b1;
            if (tick) begin
                phase <= 32'd0;
                dly1  <= integ2;
                dly2  <= comb1;
                pcm   <= comb2;
                armed <= 1'b1;
            end else begin
                phase <= phase + 32'd1;
            end
        end
    end

    assign o_pcm = pcm;

    always @(posedge clk) assert (!armed || pcm == 32'd0 || seen_one);
endmodule

