module cdc_line_edge_fifo (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire [127:0] din,
    input  wire         rd_en,
    input  wire         cfg_set,
    output wire [127:0] dout,
    output reg          full,
    output reg          empty
);
    reg [127:0] prev;
    reg [127:0] mem [0:15];
    reg [3:0]   wr_ptr;
    reg [3:0]   rd_ptr;
    reg [4:0]   count;
    reg         armed;
    reg         pv;
    integer i;

    initial begin
        prev   = 128'd0;
        wr_ptr = 4'd0;
        rd_ptr = 4'd0;
        count  = 5'd0;
        full   = 1'b0;
        empty  = 1'b1;
        armed  = 1'b0;
        pv     = 1'b0;
        for (i = 0; i < 16; i = i + 1) mem[i] = 128'd0;
    end

    wire edge_seen = en && (din != prev);
    wire push = edge_seen && !full;
    wire pop  = en && rd_en && !empty;
    wire [4:0] count_next = count + {4'd0, push} - {4'd0, pop};

    assign dout = mem[rd_ptr];

    always @(posedge clk) begin
        if (!rst_n) begin
            prev   <= 128'd0;
            wr_ptr <= 4'd0;
            rd_ptr <= 4'd0;
            count  <= 5'd0;
            full   <= 1'b0;
            empty  <= 1'b1;
            armed  <= 1'b0;
        end else if (en) begin
            prev <= din;
            if (push) begin
                mem[wr_ptr] <= din;
                wr_ptr <= wr_ptr + 4'd1;
            end
            if (pop)
                rd_ptr <= rd_ptr + 4'd1;
            count <= count_next;
            full  <= (count_next == 5'd16);
            empty <= (count_next == 5'd0);
            armed <= armed | cfg_set;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && rst_n && armed && $rose(edge_seen))
            assert (!(full && empty));
endmodule

