            min1      <= {W{1'b1}};
            min2      <= {W{1'b1}};
            min_idx   <= {W{1'b0}};
            sign_prod <= 1'b0;
            state     <= S_ACCUM;
        end
    end

    assign out_min1 = min1;
    assign out_min2 = min2;
