module thr_cross_det #(
    parameter W = 32,
    parameter [W-1:0] THR_INIT = 32'h8000_0000
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         i_ce,
    input  wire         i_load,
    input  wire [W-1:0] i_thr,
    input  wire [W-1:0] i_sample,
    output reg          o_xflag,
    output reg          o_xdir,
    output reg  [W-1:0] o_xcnt
);
    reg [W-1:0] thr;
    reg [W-1:0] prev;
    reg         have_prev;
    reg         seen_below;

    initial begin
        thr        = THR_INIT;
        prev       = {W{1'b0}};
        have_prev  = 1'b0;
        seen_below = 1'b0;
        o_xflag    = 1'b0;
        o_xdir     = 1'b0;
        o_xcnt     = {W{1'b0}};
    end

    wire s_below = (i_sample < thr);
    wire p_below = (prev < thr);
    wire cross   = have_prev && (s_below != p_below);

    always @(posedge clk) begin
        if (rst) begin
            thr        <= THR_INIT;
            prev       <= {W{1'b0}};
            have_prev  <= 1'b0;
            seen_below <= 1'b0;
            o_xflag    <= 1'b0;
            o_xdir     <= 1'b0;
            o_xcnt     <= {W{1'b0}};
        end else if (i_load) begin
            thr        <= i_thr;
            have_prev  <= 1'b0;
            seen_below <= 1'b0;
            o_xflag    <= 1'b0;
        end else if (i_ce) begin
            prev      <= i_sample;
            have_prev <= 1'b1;
            if (s_below)
                seen_below <= 1'b1;
            o_xflag <= cross;
            if (cross) begin
                o_xdir <= p_below;
                o_xcnt <= o_xcnt + 1'b1;
            end
        end
    end

    always @(*) assert (!(o_xflag && o_xdir) || seen_below);
endmodule

