module islip_alloc #(
    parameter N  = 4,
    parameter W  = 2,
    parameter CW = 64
) (
    input  wire           clk,
    input  wire           rst,
    input  wire           step,
    input  wire [N*N-1:0] req,
    input  wire [N-1:0]   rel,
    output reg  [N-1:0]   in_busy,
    output reg  [N*W-1:0] in_dst,
    output reg  [N-1:0]   out_busy,
    output reg  [N*W-1:0] out_src,
    output reg  [CW-1:0]  match_count,
    output reg            armed
);
    reg [N*W-1:0] g_ptr;
    reg [N*W-1:0] a_ptr;

    initial begin
        in_busy     = {N{1'b0}};
        in_dst      = {(N*W){1'b0}};
        out_busy    = {N{1'b0}};
        out_src     = {(N*W){1'b0}};
        g_ptr       = {(N*W){1'b0}};
        a_ptr       = {(N*W){1'b0}};
        match_count = {CW{1'b0}};
        armed       = 1'b0;
    end

    // grant phase: each free output picks a free requesting input, round robin from g_ptr
    integer gi, go, gk;
    reg [W-1:0]   tmp_g;
    reg [N-1:0]   gnt_v;
    reg [N*W-1:0] gnt_in;
    always @(*) begin
        gnt_v  = {N{1'b0}};
        gnt_in = {(N*W){1'b0}};
        tmp_g  = {W{1'b0}};
        for (go = 0; go < N; go = go + 1)
            for (gk = N-1; gk >= 0; gk = gk - 1) begin
                tmp_g = g_ptr[go*W +: W] + gk;
                for (gi = 0; gi < N; gi = gi + 1)
                    if (tmp_g == gi && !out_busy[go] && !in_busy[gi] && req[gi*N+go]) begin
                        gnt_v[go] = 1'b1;
                        gnt_in[go*W +: W] = gi;
                    end
            end
    end

    // accept phase: each free input accepts one granting output, round robin from a_ptr
    integer ai, ao, ak;
    reg [W-1:0]   tmp_a;
    reg [N-1:0]   acc_v;
    reg [N*W-1:0] acc_out;
    always @(*) begin
        acc_v   = {N{1'b0}};
        acc_out = {(N*W){1'b0}};
        tmp_a   = {W{1'b0}};
        for (ai = 0; ai < N; ai = ai + 1)
            for (ak = N-1; ak >= 0; ak = ak - 1) begin
                tmp_a = a_ptr[ai*W +: W] + ak;
                for (ao = 0; ao < N; ao = ao + 1)
                    if (tmp_a == ao && !in_busy[ai] && gnt_v[ao] && gnt_in[ao*W +: W] == ai) begin
                        acc_v[ai] = 1'b1;
                        acc_out[ai*W +: W] = ao;
                    end
            end
    end

    // next-state: releases tear down, accepted matches connect, pointers advance only on accept
    integer ni, no;
    reg [N-1:0]   in_busy_n;
    reg [N*W-1:0] in_dst_n;
    reg [N-1:0]   out_busy_n;
    reg [N*W-1:0] out_src_n;
    reg [N*W-1:0] g_ptr_n;
    reg [N*W-1:0] a_ptr_n;
    reg [W:0]     n_acc;
    always @(*) begin
        in_busy_n  = in_busy;
        in_dst_n   = in_dst;
        out_busy_n = out_busy;
        out_src_n  = out_src;
        g_ptr_n    = g_ptr;
        a_ptr_n    = a_ptr;
        n_acc      = {(W+1){1'b0}};
        for (ni = 0; ni < N; ni = ni + 1) begin
            if (rel[ni] && in_busy[ni])
                in_busy_n[ni] = 1'b0;
            if (acc_v[ni]) begin
                in_busy_n[ni]        = 1'b1;
                in_dst_n[ni*W +: W]  = acc_out[ni*W +: W];
                a_ptr_n[ni*W +: W]   = acc_out[ni*W +: W] + 1'b1;
                n_acc                = n_acc + 1'b1;
            end
            for (no = 0; no < N; no = no + 1) begin
                if (rel[ni] && in_busy[ni] && in_dst[ni*W +: W] == no)
                    out_busy_n[no] = 1'b0;
                if (acc_v[ni] && acc_out[ni*W +: W] == no) begin
                    out_busy_n[no]       = 1'b1;
                    out_src_n[no*W +: W] = ni;
                    g_ptr_n[no*W +: W]   = ni + 1;
                end
            end
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            in_busy     <= {N{1'b0}};
            in_dst      <= {(N*W){1'b0}};
            out_busy    <= {N{1'b0}};
            out_src     <= {(N*W){1'b0}};
            g_ptr       <= {(N*W){1'b0}};
            a_ptr       <= {(N*W){1'b0}};
            match_count <= {CW{1'b0}};
        end else if (step) begin
            in_busy     <= in_busy_n;
            in_dst      <= in_dst_n;
            out_busy    <= out_busy_n;
            out_src     <= out_src_n;
            g_ptr       <= g_ptr_n;
            a_ptr       <= a_ptr_n;
            match_count <= match_count + n_acc;
            if (|acc_v)
                armed <= 1'b1;
        end
    end

    // absence: two inputs never own the same output (after the first match)
    integer pi, pj;
    reg dup;
    always @(*) begin
        dup = 1'b0;
        for (pi = 0; pi < N; pi = pi + 1)
            for (pj = pi + 1; pj < N; pj = pj + 1)
                if (in_busy[pi] && in_busy[pj] && in_dst[pi*W +: W] == in_dst[pj*W +: W])
                    dup = 1'b1;
    end

    assert property (!armed || !dup);
endmodule

