module morse_decoder #(
    parameter SRW = 8,
    parameter [7:0] MAXSYM = 8'd7,
    parameter [7:0] DOT_MAX = 8'd3,
    parameter [7:0] CHAR_GAP = 8'd5
) (
    input wire clk,
    input wire rst,
    input wire step,
    input wire key,
    output reg [SRW-1:0] char_code,
    output reg [7:0] char_len,
    output reg char_valid
);
    typedef enum logic [1:0] {IDLE = 2'd0, MARK = 2'd1, SPACE = 2'd2} state_t;
    state_t state;
    reg [7:0] dur;
    reg [SRW-1:0] sym_sr;
    reg [7:0] sym_cnt;
    reg armed;

    initial begin
        state = IDLE;
        dur = 8'd0;
        sym_sr = {{(SRW-1){1'b0}}, 1'b1};
        sym_cnt = 8'd0;
        armed = 1'b0;
        char_code = {SRW{1'b0}};
        char_len = 8'd0;
        char_valid = 1'b0;
    end

    wire is_dash = (dur > DOT_MAX);
    wire [7:0] dur_inc = (dur == 8'hFF) ? dur : (dur + 8'd1);

    always @(posedge clk) begin
        if (rst) begin
            state <= IDLE;
            dur <= 8'd0;
            sym_sr <= {{(SRW-1){1'b0}}, 1'b1};
            sym_cnt <= 8'd0;
            armed <= 1'b0;
            char_code <= {SRW{1'b0}};
            char_len <= 8'd0;
            char_valid <= 1'b0;
        end else if (step) begin
            char_valid <= 1'b0;
            case (state)
                IDLE: begin
                    if (key) begin
                        state <= MARK;
                        dur <= 8'd1;
                    end
                end
                MARK: begin
                    if (key) begin
                        dur <= dur_inc;
                    end else begin
                        if (sym_cnt < MAXSYM) begin
                            sym_sr <= {sym_sr[SRW-2:0], is_dash};
                            sym_cnt <= sym_cnt + 8'd1;
                        end
                        armed <= 1'b1;
                        state <= SPACE;
                        dur <= 8'd1;
                    end
                end
                SPACE: begin
                    if (key) begin
                        state <= MARK;
                        dur <= 8'd1;
                    end else if (dur_inc >= CHAR_GAP) begin
                        char_code <= sym_sr;
                        char_len <= sym_cnt;
                        char_valid <= 1'b1;
                        sym_sr <= {{(SRW-1){1'b0}}, 1'b1};
                        sym_cnt <= 8'd0;
                        armed <= 1'b0;
                        state <= IDLE;
                        dur <= 8'd0;
                    end else begin
                        dur <= dur_inc;
                    end
                end
                default: state <= IDLE;
            endcase
        end
    end

    // Scope: after a symbol is accepted (armed set) until the character is emitted (armed cleared)
    always @(posedge clk)
        if (armed)
            assert (sym_sr != {{(SRW-1){1'b0}}, 1'b1});

    always @(posedge clk)
        if (armed && sym_cnt < MAXSYM)
            assert (sym_sr[SRW-1] == 1'b0);
endmodule


