module div3_serial #(
    parameter W = 16,
    parameter MAXBITS = 16
) (
    input  wire         clk,
    input  wire         arm,
    input  wire         clr,
    input  wire         load,
    input  wire [W-1:0] load_len,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire         in_bit,
    output wire         done,
    output wire         div3,
    output wire [1:0]   o_rem
);
    localparam [1:0] S_IDLE = 2'd0, S_ARM = 2'd1, S_RUN = 2'd2, S_DONE = 2'd3;

    reg [1:0]   phase   = S_IDLE;
    reg [1:0]   rem     = 2'd0;
    reg [W-1:0] val     = {W{1'b0}};
    reg [W-1:0] cnt     = {W{1'b0}};
    reg [W-1:0] limit   = 16'd8;
    reg         started = 1'b0;
    reg         win     = 1'b0;

    assign in_ready = (phase == S_ARM) || (phase == S_RUN);
    wire acc = in_valid && in_ready;

    function [1:0] rnext;
        input [1:0] r;
        input       b;
        begin
            case ({r, b})
                3'b000: rnext = 2'd0;
                3'b001: rnext = 2'd1;
                3'b010: rnext = 2'd2;
                3'b011: rnext = 2'd0;
                3'b100: rnext = 2'd1;
                3'b101: rnext = 2'd2;
                default: rnext = 2'd0;
            endcase
        end
    endfunction

    wire [W-1:0] load_clamped = (load_len == 16'd0) ? 16'd1 :
                                (load_len > MAXBITS) ? MAXBITS : load_len;

    always @(posedge clk) begin
        if (phase == S_IDLE) begin
            if (load) limit <= load_clamped;
            if (arm) begin
                phase   <= S_ARM;
                rem     <= 2'd0;
                val     <= {W{1'b0}};
                cnt     <= {W{1'b0}};
                started <= 1'b0;
                win     <= 1'b1;
            end
        end else if (phase == S_DONE) begin
            if (clr) begin
                phase   <= S_IDLE;
                rem     <= 2'd0;
                val     <= {W{1'b0}};
                cnt     <= {W{1'b0}};
                started <= 1'b0;
                win     <= 1'b0;
            end
        end else if (acc) begin
            rem     <= rnext(rem, in_bit);
            val     <= {val[W-2:0], in_bit};
            cnt     <= cnt + 16'd1;
            started <= 1'b1;
            if (cnt + 16'd1 == limit) phase <= S_DONE;
            else                      phase <= S_RUN;
        end
    end

    assign done  = (phase == S_DONE);
    assign div3  = (rem == 2'd0);
    assign o_rem = rem;

    always @(posedge clk)
        if (win && $rose(done))
            assert (started && (div3 == ((val % 16'd3) == 16'd0)));
endmodule


