            if (aw_hs) begin
                phase      <= P_ARMED;
                aw_seen    <= 1'b1;
                beats_left <= i_awlen;
                cap_size   <= i_awsize;
                lane       <= {LW{1'b0}};
                strb       <= {SW{1'b0}};
