                end
                ARMED: begin
                    if (mutex_gnt) begin
                        clk_en <= 1'b0;
                        phase <= STARTED;
                        start_cnt <= start_cnt + 32'd1;
                    end
                end
                STARTED: begin
                    wptr <= wptr + 8'd1;
                    hs_latch <= 1'b0;
                    clk_en <= 1'b1;
                    phase <= IDLE;
                    fin_cnt <= fin_cnt + 32'd1;
