module pam4_gray_mapper #(
    parameter CW = 32
) (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       slip,
    input  wire       precode_en,
    input  wire       din,
    output reg  [1:0] sym_out,
    output reg        sym_valid,
    output wire       pair_pending
);
    // bit-pair staging register
    reg          stage_bit;
    reg          half;
    // precoder previous-symbol register
    reg  [1:0]   prev_sym;
    // statistics
    reg  [CW-1:0] bit_cnt;
    reg  [CW-1:0] sym_cnt;
    reg  [CW-1:0] drop_cnt;
    // scope register: high until the first bit slip
    reg          armed;

    initial begin
        stage_bit = 1'b0;
        half      = 1'b0;
        prev_sym  = 2'd0;
        bit_cnt   = {CW{1'b0}};
        sym_cnt   = {CW{1'b0}};
        drop_cnt  = {CW{1'b0}};
        armed     = 1'b1;
        sym_out   = 2'd0;
        sym_valid = 1'b0;
    end

    wire [1:0] pair  = {stage_bit, din};
    // Gray map: 00->0, 01->1, 11->2, 10->3
    wire [1:0] level = {pair[1], pair[1] ^ pair[0]};
    wire [1:0] coded = precode_en ? (level - prev_sym) : level;

    always @(posedge clk) begin
        if (rst) begin
            stage_bit <= 1'b0;
            half      <= 1'b0;
            prev_sym  <= 2'd0;
            bit_cnt   <= {CW{1'b0}};
            sym_cnt   <= {CW{1'b0}};
            drop_cnt  <= {CW{1'b0}};
            armed     <= 1'b1;
            sym_out   <= 2'd0;
            sym_valid <= 1'b0;
        end else if (ce) begin
            if (slip) begin
                armed     <= 1'b0;
                sym_valid <= 1'b0;
                if (half) begin
                    half     <= 1'b0;
                    drop_cnt <= drop_cnt + {{(CW-1){1'b0}}, 1'b1};
                end
            end else begin
                bit_cnt <= bit_cnt + {{(CW-1){1'b0}}, 1'b1};
                if (!half) begin
                    stage_bit <= din;
                    half      <= 1'b1;
                    sym_valid <= 1'b0;
                end else begin
                    half      <= 1'b0;
                    sym_cnt   <= sym_cnt + {{(CW-1){1'b0}}, 1'b1};
