// After captures begin, check the address written by each capture.
always @(posedge clk) begin
    assert (ar_capture_pv ?
        (!$past(s_axi_arready) ||
         (m_axi_araddr == $past(s_axi_araddr))) :
        (m_axi_arvalid ||
         (m_axi_araddr == {ADDR_WIDTH{1'b0}})));
